function stopNarration(){if('speechSynthesis' in window)speechSynthesis.cancel()}
function openPlaceDialog(){const d=$('placeDialog');if(!d.open)d.showModal();d.scrollTop=0}
function startPlaceNarration(site){stopNarration();const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('ca'));const status=document.createElement('p');status.className='muted';status.setAttribute('role','status');$('placeDetail').querySelector('.place-actions').appendChild(status);if(!voice){status.textContent='No hem trobat una veu catalana. Activa-la a les veus del dispositiu.';return}const u=new SpeechSynthesisUtterance(site.name+'. '+site.origin);u.lang='ca-ES';u.voice=voice;u.rate=.9;u.onend=()=>status.textContent='Lectura acabada';u.onerror=()=>status.textContent='No s’ha pogut iniciar la lectura';speechSynthesis.speak(u);status.textContent='Llegint en català…';}
