let mapInstance=null,lastLookup=0,activePin=null,lookupController=null,lookupVersion=0;
function distanceKm(a,b,c,d){const rad=Math.PI/180;const x=(c-a)*rad,y=(d-b)*rad;const h=Math.sin(x/2)**2+Math.cos(a*rad)*Math.cos(c*rad)*Math.sin(y/2)**2;return 12742*Math.asin(Math.min(1,Math.sqrt(h)))}
const locationPhotos={
"Xcaret":"https://images.unsplash.com/photo-1512813195386-6cf811ad3542?w=1100",
"Memfis":"https://images.unsplash.com/photo-1539768942893-daf53e448371?w=1100",
"Uruk":"assets/uruk-aster.jpg",
"Atenes":"https://images.unsplash.com/photo-1555993539-1732b0258235?w=1100",
"Roma":"https://images.unsplash.com/photo-1552832230-c0197dd311b5?w=1100",
"Barcelona":"https://images.unsplash.com/photo-1539037116277-4db20889f2d4?w=1100",
"Pequín":"https://images.unsplash.com/photo-1508804185872-d7badad00f7d?w=1100",
"Cusco":"https://images.unsplash.com/photo-1526392060635-9d6019884377?w=1100"
};
function photoFor(site){const key=Object.keys(locationPhotos).find(k=>site.name.includes(k));return locationPhotos[key]||'https://images.unsplash.com/photo-1461360370896-922624d12aa1?w=1100'}
function siteDetails(site){lookupVersion++;if(lookupController)lookupController.abort();const box=$('placeDetail');box.innerHTML='';
const img=document.createElement('img');img.src=photoFor(site);img.alt='Fotografia d’ambientació, no necessàriament del lloc exacte';img.className='place-cover';box.appendChild(img);
const kicker=document.createElement('div');kicker.className='place-kicker';kicker.textContent='Viatge històric · Explora el territori';box.appendChild(kicker);
const h=document.createElement('h2');h.textContent=site.name;h.style.margin='8px 0';box.appendChild(h);
const subtitle=document.createElement('p');subtitle.className='lead';subtitle.textContent='Una finestra al passat d’aquest territori';box.appendChild(subtitle);
const actions=document.createElement('div');actions.className='place-actions';box.appendChild(actions);
const read=document.createElement('button');read.textContent='📖 Llegir el conte';read.onclick=()=>box.querySelector('.place-story').scrollIntoView({behavior:'smooth',block:'start'});actions.appendChild(read);
const listen=document.createElement('button');listen.textContent='♫ Escoltar';listen.onclick=()=>{if(!('speechSynthesis' in window))return;startPlaceNarration(site)};actions.appendChild(listen);
const heading=document.createElement('h3');heading.textContent='La història d’aquest lloc';heading.className='place-story';box.appendChild(heading);
const p=document.createElement('p');p.className='lead';p.textContent=site.origin;box.appendChild(p);
const note=document.createElement('p');note.className='lead';note.textContent=site.more;box.appendChild(note);
const timeline=document.createElement('h3');timeline.textContent='El viatge a través del temps';box.appendChild(timeline);
const stages=document.createElement('div');stages.className='place-epochs';box.appendChild(stages);
const eras=site.timeline||[['Orígens coneguts',site.origin],['Per continuar',site.more]];
eras.forEach(([name,desc])=>{const e=document.createElement('div');e.className='place-epoch';const strong=document.createElement('strong');strong.textContent=name;e.appendChild(strong);e.appendChild(document.createTextNode(desc));stages.appendChild(e)});
const stop=document.createElement('button');stop.textContent='Atura la veu';stop.onclick=stopNarration;actions.appendChild(stop);const caveat=document.createElement('p');caveat.className='muted';caveat.textContent='Resum introductori. Les dates antigues poden ser aproximades. Les fotografies són d’ambientació.';box.appendChild(caveat);if(site.sources){const sources=document.createElement('div');sources.className='sources';sources.innerHTML='<strong>Per saber-ne més</strong>'+site.sources.map(([name,url])=>'<a href="'+url+'" target="_blank" rel="noopener">'+name+' ↗</a>').join('');box.appendChild(sources)}
if(site.chapter!==null){const b=document.createElement('button');b.className='btn';b.textContent='Obrir un capítol relacionat';b.onclick=()=>{const i=site.chapter;$('placeDialog').close();volumeIndex=assignment[i][0];shelfIndex=shelves.findIndex(f=>volumeIndex>=f.range[0]&&volumeIndex<f.range[1]);switchTab('historia');readStory(i)};box.appendChild(b)}
openPlaceDialog()
}
async function clickMap(lat,lng){const version=++lookupVersion;if(lookupController)lookupController.abort();lookupController=new AbortController();openPlaceDialog();let nearest=historicalSites.map(p=>({p,d:distanceKm(lat,lng,p.lat,p.lng)})).sort((a,b)=>a.d-b.d)[0];if(nearest.d<45){siteDetails(nearest.p);return}const box=$('placeDetail');box.innerHTML='<h3>Explorant aquest indret…</h3><p class="lead">Busquem el nom del lloc. Encara no tenim una història documentada per a tots els punts del mapa.</p>';const now=Date.now();if(now-lastLookup<1100){box.innerHTML='<h3>Punt seleccionat</h3><p>Per descobrir un altre indret, espera un moment o toca un dels punts històrics destacats.</p>';return}lastLookup=now;try{const resp=await fetch('https://nominatim.openstreetmap.org/reverse?format=jsonv2&zoom=8&accept-language=ca&lat='+encodeURIComponent(lat)+'&lon='+encodeURIComponent(lng),{signal:lookupController.signal});if(!resp.ok)throw Error('Sense resposta');const data=await resp.json();if(version!==lookupVersion)return;const name=data.name||data.address?.city||data.address?.state||data.address?.country||'Lloc seleccionat';box.innerHTML='';const h=document.createElement('h3');h.textContent=name;box.appendChild(h);const p=document.createElement('p');p.textContent='Has seleccionat aquest lloc del mapa. Encara no tenim una narració històrica local verificada per a aquest punt. Pots explorar els marcadors destacats mentre ampliem la biblioteca.';box.appendChild(p);const small=document.createElement('p');small.className='muted';small.textContent='Nom geogràfic: © OpenStreetMap / Nominatim. Les fronteres actuals no equivalen a les històriques.';box.appendChild(small)}catch(e){if(e.name==='AbortError'||version!==lookupVersion)return;box.innerHTML='<h3>Punt seleccionat</h3><p>No hem pogut identificar el nom del lloc. Prova de tocar un dels marcadors històrics.</p>'}}
function initMap(){renderMapFeatures();if(mapInstance){mapInstance.invalidateSize();if(typeof addColorfulCountries==='function')addColorfulCountries(mapInstance);return}if(typeof L==='undefined'){$('realMap').innerHTML='<div class="panel"><h3>El mapa necessita connexió</h3><p>Pots obrir les històries amb les finestres de llocs de dalt. Torna a entrar al mapa per intentar carregar-lo de nou.</p></div>';return}mapInstance=L.map('realMap',{worldCopyJump:true,zoomSnap:.25,minZoom:.5,maxZoom:10,maxBounds:[[-85,-190],[85,190]],maxBoundsViscosity:.8}).setView([25,12],2);if(typeof addColorfulCountries==='function')addColorfulCountries(mapInstance);historicalSites.forEach(site=>{const marker=L.marker([site.lat,site.lng],{title:site.name,alt:site.name}).addTo(mapInstance);marker.bindTooltip('<strong>'+site.name+'</strong><br>'+site.origin.slice(0,180)+'…',{className:'history-tooltip',direction:'top'});marker.on('mouseover',()=>showPlacePreview(site));marker.on('click',()=>siteDetails(site))});mapInstance.on('click',e=>clickMap(e.latlng.lat,e.latlng.lng));setTimeout(()=>mapInstance.invalidateSize(),120)}
function renderMapFeatures(){if($('mapFeatures').children.length)return;historicalSites.forEach(site=>{const b=document.createElement('button');b.className='map-feature';const img=document.createElement('img');img.src=photoFor(site);img.alt='Imatge d’ambientació';img.loading='lazy';b.appendChild(img);const t=document.createElement('span');t.textContent=site.name.split(' · ')[0];b.appendChild(t);b.onclick=()=>{if(mapInstance)mapInstance.setView([site.lat,site.lng],6);siteDetails(site)};$('mapFeatures').appendChild(b)})}
$('audioChapter').innerHTML=chapters.map((c,i)=>'<option value="'+i+'">'+c.title+'</option>').join('');
function updateAudioText(){stopNarration();$('audioText').innerHTML=chapters[+$('audioChapter').value].text.split(/\\n\\n|\n\n/).map(t=>'<p>'+t+'</p>').join('');$('audioText').classList.add('audio-copy')}$('audioChapter').onchange=updateAudioText;updateAudioText();
$('play').onclick=()=>{if(!('speechSynthesis' in window)){$('audioStatus').textContent='Aquest navegador no ofereix lectura de veu.';return}speechSynthesis.cancel();let c=chapters[+$('audioChapter').value],u=new SpeechSynthesisUtterance(c.title+'. '+c.text.replace(/\\n/g,' '));u.lang='ca-ES';u.rate=.9;let v=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('ca'));if(!v){$('audioStatus').textContent='No hem trobat una veu catalana. Activa-la a les veus del dispositiu.';return}u.voice=v;u.onerror=()=>$('audioStatus').textContent='No s’ha pogut iniciar la lectura';u.onend=()=>$('audioStatus').textContent='Lectura acabada';speechSynthesis.speak(u);$('audioStatus').textContent=v?'Llegint en català…':'Comprova les veus del dispositiu per escoltar en català.'};
$('pause').onclick=()=>{if(!('speechSynthesis' in window))return;if(speechSynthesis.paused){speechSynthesis.resume();$('audioStatus').textContent='Lectura represa'}else{speechSynthesis.pause();$('audioStatus').textContent='Lectura en pausa'}};
$('stop').onclick=()=>{if('speechSynthesis' in window)speechSynthesis.cancel();$('audioStatus').textContent='Lectura aturada'};
function showQuiz(){let q=questions[quizIndex];$('quiz').innerHTML='<small class="muted">Pregunta '+(quizIndex+1)+' de '+questions.length+'</small><h3>'+q.q+'</h3><div class="choices">'+q.options.map((o,i)=>'<button data-answer="'+i+'">'+o+'</button>').join('')+'</div><p id="feedback" role="status"></p><button class="btn hidden" id="next">Següent pregunta</button>';$('quiz').onclick=e=>{let b=e.target.closest('[data-answer]');if(b){document.querySelectorAll('[data-answer]').forEach(x=>{x.disabled=true;if(+x.dataset.answer===q.correct)x.classList.add('correct');else if(x===b)x.classList.add('wrong')});$('feedback').textContent=q.why;$('next').classList.remove('hidden')}if(e.target.id==='next'){quizIndex=(quizIndex+1)%questions.length;showQuiz()}}}showQuiz();
$('surprise').onclick=()=>{let i=Math.floor(Math.random()*chapters.length);let v=assignment[i][0];volumeIndex=v;shelfIndex=shelves.findIndex(f=>v>=f.range[0]&&v<f.range[1]);switchTab('historia');readStory(i)};

$('dialogBody').appendChild($('placeDetail'));$('closePlace').onclick=()=>$('placeDialog').close();$('placeDialog').addEventListener('close',stopNarration);$('placeDialog').addEventListener('click',e=>{if(e.target===$('placeDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('beginJourney').onclick=()=>$('epochsTitle').scrollIntoView({behavior:'smooth'});
const artKinds=['origins','ancient','medieval','modern','industry','today'];shelves.forEach((f,i)=>f.image='assets/'+artKinds[i]+'-ia.jpg');document.querySelectorAll('[data-shelf] img').forEach((img,i)=>img.src=shelves[i].image);document.querySelectorAll('[data-door] img').forEach((img,i)=>{img.src='assets/'+['modern','atlas','medieval'][i]+'-ia.jpg';img.alt='Escena d’ambientació creada amb IA'});
$('librarySearch').addEventListener('input',e=>{const q=e.target.value.trim().toLocaleLowerCase('ca');$('folders').classList.toggle('hidden',!!q);const results=chapters.map((c,i)=>({c,i})).filter(({c})=>(c.title+' '+c.short+' '+c.text).toLocaleLowerCase('ca').includes(q));$('libraryResults').innerHTML=q?(results.length?results.map(({c,i})=>'<article class="story-card"><div class="inside"><small class="muted">'+c.period+'</small><h3>'+c.title+'</h3><p>'+c.short+'</p><button class="btn" data-result="'+i+'">Llegir la història</button></div></article>').join(''):'<p class="empty">No hem trobat aquesta història. Prova una altra paraula.</p>'):''});$('libraryResults').onclick=e=>{const b=e.target.closest('[data-result]');if(!b)return;const i=+b.dataset.result;volumeIndex=assignment[i][0];shelfIndex=shelves.findIndex(f=>volumeIndex>=f.range[0]&&volumeIndex<f.range[1]);readStory(i)};

document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&!e.target.dataset.fallback){e.target.dataset.fallback='true';e.target.src='assets/atlas-ia.jpg';e.target.alt='Atles imaginari creat amb IA'}},true);
